import type { Scene } from "@/lib/panel-focus";

const SCENES: Scene[] = ["aube", "matin", "dore", "nuit"];

// The painted gate above Bali (generated by Nathan, public/panel/*.jpg): the four times of day are stacked and
// cross-fade, so the background changes with the step without a flash.
export function Backdrop({ scene }: { scene: Scene }) {
  return (
    <div aria-hidden className="np-backdrop">
      {SCENES.map((name) => (
        <div key={name} className="np-scene" data-on={name === scene} style={{ backgroundImage: `url(/panel/${name}.jpg)` }} />
      ))}
    </div>
  );
}
